import json, re, subprocess, pathlib, hashlib, collections
P='plans/260925-documentation-authority-unification'
PIN=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
M=json.loads(pathlib.Path(P+'/reports/phase-08/step-08-tree-prune-manifest.json').read_text())
removed={r['path']:r for r in M['inventory'] if r['action']=='remove'}
byname=collections.defaultdict(list)
for p in removed:byname[pathlib.PurePosixPath(p).name].append(p)
namepat=re.compile(r'(?<![A-Za-z0-9_.-])[A-Za-z0-9_.-]+\.(?:jsonl?|md|log|gz)(?:\.json)?')
code=re.compile(r'(?:\b(?:import |from \S+ import |const |let |var |function |def |class |assert |return |for \w+ in |JSON\.(?:parse|stringify)|fs\.|readFile|read_text\(|read_bytes\(|json\.load|subprocess\.|readdir|\.glob\(|\.rglob\(|\.write_text\(|open\()|(?:^|\n)\s*(?:env |node |python[23]? |bash |sh |git |npm ))')
listing=subprocess.check_output(['git','ls-tree','-r','-z',PIN,'--',P]).split(b'\0')
entries=[e.split(b'\t',1) for e in listing if e]
batch=subprocess.Popen(['git','cat-file','--batch'],stdin=subprocess.PIPE,stdout=subprocess.PIPE)
bodies=[]; files=[]; candidates=[]; enumeration=[]
def add(path,field,src,physical=None):
 if field.startswith('fence@'):
  try:
   value=json.loads(src)
  except ValueError:pass
  else:
   walk(path,value,field+'#');return
 if not code.search(src) and not field.startswith('fence@') and not field.endswith('#argv') and not path.endswith(('.py','.mjs','.js','.cjs','.sh','.bash')):return
 bodies.append({'readerPath':path,'field':field,'lines':len(src.splitlines())})
 lines=src.splitlines()
 for i,line in enumerate(lines,1):
  base={'readerPath':path,'field':field,'line':i,'physicalLine':physical,'text':line,'context':'\n'.join(lines[max(0,i-4):min(len(lines),i+3)])}
  matches=sorted({p for m in namepat.finditer(line) for p in byname.get(m.group(),[])})
  if matches:candidates.append(dict(base,targets=matches))
  if re.search(r'glob|readdir|listdir|iterdir|walk\(|find .*-(?:name|path)|\.filter\(|startsWith\(|endsWith\(',line):enumeration.append(base)
def walk(path,value,field=''):
 if isinstance(value,dict):
  for k,v in value.items():walk(path,v,field+'/'+str(k).replace('~','~0').replace('/','~1'))
 elif isinstance(value,list):
  if field.rsplit('/',1)[-1].lower() in ('command','argv','cmd','args') and all(isinstance(v,str) for v in value) and not any(v in ('-e','--eval','-c') for v in value):add(path,field+'#argv',' '.join(value))
  for i,v in enumerate(value):walk(path,v,field+'/'+str(i))
 elif isinstance(value,str) and code.search(value):add(path,field,value)
for meta,pathbytes in entries:
 mode,typ,oid=meta.split();path=pathbytes.decode()
 if typ!=b'blob' or mode==b'120000':continue
 batch.stdin.write(oid+b'\n');batch.stdin.flush();header=batch.stdout.readline();size=int(header.split()[2]);data=batch.stdout.read(size);assert batch.stdout.read(1)==b'\n'
 text=data.decode('utf-8',errors='replace');files.append({'path':path,'gitBlob':oid.decode(),'bytes':size})
 if len(files)%100==0: print(len(files),path,flush=True,file=__import__('sys').stderr)
 suffix=pathlib.PurePosixPath(path).suffix
 if suffix in ('.py','.mjs','.js','.cjs','.sh','.bash','.ts','.tsx','.rs'):add(path,'',text)
 elif suffix=='.json':
  try:walk(path,json.loads(text))
  except ValueError: add(path,'raw',text)
 elif suffix=='.jsonl':
  for i,l in enumerate(text.splitlines(),1):
   try:walk(path,json.loads(l),'line:'+str(i))
   except ValueError:add(path,'line:'+str(i),l,i)
 elif suffix=='.md':
  start=None;block=[]
  for i,l in enumerate(text.splitlines(),1):
   if l.startswith('```') or l.startswith('~~~'):
    if start is None:start=i+1;block=[]
    else:add(path,'fence@'+str(start),'\n'.join(block),start);start=None
   elif start is not None:block.append(l)
   elif code.search(l):add(path,'inline@'+str(i),l,i)
  if start is not None:add(path,'fence@'+str(start),'\n'.join(block),start)
 elif code.search(text):add(path,'raw',text)
batch.stdin.close();batch.wait()
out={'inputCommit':PIN,'scope':P,'filesScanned':len(files),'bytesScanned':sum(f['bytes'] for f in files),'bodies':bodies,'literalCandidates':candidates,'enumerationCandidates':enumeration,'files':files}
pathlib.Path('/tmp/fgos-work/closure-r3/scan.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:len(v) if isinstance(v,list) else v for k,v in out.items()}))
for c in candidates:print(c['readerPath'].removeprefix(P+'/')+'#'+c['field']+':'+str(c['line']),','.join(pathlib.PurePosixPath(p).name for p in c['targets']),c['text'][:300])
